+/* ============================================================
+   Club groups.
+
+   The selected group uses a persistent rail on wider screens and
+   a compact horizontal chooser on phones. The split owns its own
+   spacing so the wide member-app layout can sit flush in the card.
+   ============================================================ */
+.club-groups {
+  width: 100%;
+}
+
+.app-split {
+  display: grid;
+  grid-template-columns: 210px minmax(0, 1fr);
+  min-height: 560px;
+}
+
+.group-content {
+  min-width: 0;
+  padding-bottom: 28px;
+}
+
+.group-rail {
+  min-width: 0;
+  padding: 24px 12px;
+  border-right: 1px solid var(--color-line);
+  background: color-mix(in srgb, var(--color-cream) 72%, var(--color-paper));
+}
+
+.group-rail__label {
+  padding: 0 11px 9px;
+  color: var(--color-ink-3);
+  font-size: 11px;
+  font-weight: 700;
+  letter-spacing: 0.08em;
+  line-height: 1.2;
+  text-transform: uppercase;
+}
+
+.group-rail__item {
+  min-height: 40px;
+  margin-top: 2px;
+  padding: 9px 11px;
+  border-radius: 9px;
+  color: var(--color-ink-2);
+  display: flex;
+  align-items: center;
+  gap: 8px;
+  font-size: 13.5px;
+  font-weight: 600;
+  line-height: 1.35;
+  text-decoration: none;
+  transition:
+    background-color 120ms cubic-bezier(0.22, 0.61, 0.36, 1),
+    color 120ms cubic-bezier(0.22, 0.61, 0.36, 1),
+    transform 120ms cubic-bezier(0.22, 0.61, 0.36, 1);
+}
+
+.group-rail__item:hover {
+  background: var(--color-sage-50);
+  color: var(--color-sage-700);
+}
+
+.group-rail__item:focus-visible {
+  outline: 2px solid var(--color-sage-400);
+  outline-offset: 1px;
+}
+
+.group-rail__item.is-active {
+  background: var(--color-sage-100);
+  color: var(--color-sage-800);
+}
+
+.group-rail__name {
+  min-width: 0;
+  overflow-wrap: anywhere;
+}
+
+.group-head {
+  padding: 28px 28px 0;
+}
+
+.group-head__top {
+  display: flex;
+  align-items: flex-start;
+  justify-content: space-between;
+  gap: 20px;
+}
+
+.group-head__name {
+  color: var(--color-ink);
+  font-size: 28px;
+  font-weight: 700;
+  letter-spacing: -0.03em;
+  line-height: 1.15;
+  overflow-wrap: anywhere;
+}
+
+.group-head__meta {
+  margin-top: 7px;
+  color: var(--color-ink-3);
+  display: flex;
+  flex-wrap: wrap;
+  align-items: center;
+  gap: 5px 14px;
+  font-size: 13px;
+  line-height: 1.45;
+}
+
+.group-head__addr {
